"""Build an offline, evidence-led diagnostic workspace from aggregate outputs."""
import html,json
import pandas as pd
from talentroute.data import ROOT
D=ROOT/'outputs/investigations';manifest=json.loads((D/'manifest.json').read_text())
curve=pd.read_csv(D/'learning_curve.csv');single=pd.read_csv(D/'single_feature.csv');shift=pd.read_csv(D/'period_shift.csv')
intervals=pd.DataFrame([json.loads((ROOT/'outputs/validation_paired_interval.json').read_text())])

def table(df):return '<div class="scroll">'+df.to_html(index=False,border=0,float_format=lambda x:f'{x:.4f}')+'</div>'
def card(k,title,question,expectation,result,limits,evidence):
 return dict(key=k,title=title,question=question,expectation=expectation,result=result,limits=limits,evidence=evidence)
def chart(model):
 rows=curve[curve.model==model].groupby(['fraction','split']).adverse_ap.agg(['mean','min','max']).reset_index()
 parts=['<svg viewBox="0 0 640 280" role="img" aria-label="Learning curve: average precision versus training fraction"><rect width="640" height="280" fill="white"/>']
 for v in [0,.25,.5,.75,1]:
  y=235-v*200;parts.append(f'<path d="M50 {y} H610" stroke="#e1e8f0"/><text x="8" y="{y+5}" font-size="12">{v:.2f}</text>')
 for split,color in [('training','#2a6fdb'),('validation','#12a594')]:
  r=rows[rows.split==split];points=' '.join(f'{50+x.fraction*550},{235-x["mean"]*200}' for _,x in r.iterrows());parts.append(f'<polyline points="{points}" fill="none" stroke="{color}" stroke-width="3"/>')
  for _,x in r.iterrows():
   px=50+x.fraction*550;py=235-x['mean']*200
   parts.append(f'<line x1="{px}" x2="{px}" y1="{235-x["max"]*200}" y2="{235-x["min"]*200}" stroke="{color}" stroke-width="5"/><circle tabindex="0" cx="{px}" cy="{py}" r="6" fill="{color}"><title>{split}; {x.fraction:.0%} of training rows; mean AP {x["mean"]:.4f}; seed range {x["min"]:.4f}–{x["max"]:.4f}</title></circle>')
 for f in [.2,.5,1]:parts.append(f'<text x="{50+f*550-16}" y="260" font-size="12">{f:.0%}</text>')
 return ''.join(parts)+'</svg><p class="muted">Blue: training · Teal: validation. Vertical marks show the range across three seeds, not confidence intervals. Horizontal axis: training fraction; vertical axis: adverse-outcome average precision (AP).</p>'
start=curve[(curve.model=='hgb_15_10')&(curve.split=='validation')].groupby('fraction').adverse_ap.mean()
top=single.iloc[0]
cards=[card('learning','01 · Learning curve','Would more data improve prediction?','If sampling is limiting performance, validation performance may rise as training size grows. A temporal change can also create a gap.',f'HGB validation AP changes from {start.loc[.2]:.4f} at 20% to {start.loc[1.]:.4f} at 100% of the training cohort.','HGB uses a fixed iteration budget with early stopping disabled for this diagnostic. Repeated samples share one validation cohort. This is exploratory evidence after model selection, not a forecast of future improvement.', ''.join('<h3>'+({'logistic':'Logistic regression','hgb_15_10':'Histogram gradient boosting'}[m])+'</h3>'+chart(m) for m in ['logistic','hgb_15_10'])+'<details><summary>All runs and seeds</summary>'+table(curve)+'</details>'),
card('feature','02 · Feature audit','Is one variable doing suspiciously well?','A strong single-feature model is a reason to inspect its source and availability date.',f'The highest single-feature validation AP is {top.adverse_ap:.4f}, from {top.feature}. The validation adverse prevalence is {manifest["validation_adverse_prevalence"]:.4f}.','Predictive strength cannot establish leakage. The audit must also check timestamps, aggregation cutoffs and target provenance. Missingness can be informative without being an error.',table(single)),
card('shift','03 · Period differences','Can a model distinguish the development periods?','A domain classifier above ROC-AUC 0.5 suggests differences in the observed predictor distributions.',f'Mean domain ROC-AUC is {shift.domain_roc_auc.mean():.4f}; seed range {shift.domain_roc_auc.min():.4f}–{shift.domain_roc_auc.max():.4f}. Students are disjoint between domain-classifier fit and evaluation subsets.','This compares training-period and validation-period features only. It does not establish concept drift, explain a performance change, or assess the final test cohort.',table(shift)),
card('decision','04 · Added-component decision','Does the engagement detector add reliable value?','Compare the connected policy against the same ensemble without the detector, under the same workload budget.','The development comparison does not establish a positive incremental detector benefit: its validation-selected paired interval includes zero. Keep classifier-only as the provisional reference.','These are exploratory validation-selected results. A separate final candidate was already evaluated on 2014J; new investigations do not reopen that test or justify retuning.',table(intervals))]
css='''*{box-sizing:border-box}body{margin:0;background:#f4f7fb;color:#1c2733;font:15px/1.5 system-ui,-apple-system,Segoe UI,sans-serif}header{background:linear-gradient(110deg,#0b3b5c,#107e79);color:white;padding:30px max(24px,calc((100vw - 1400px)/2))}header p{max-width:800px;color:#dceff1}h1{font-size:36px;margin:10px 0}h2{font-size:25px;margin:8px 0 18px}h3{font-size:16px}main{max-width:1450px;margin:auto;padding:24px}.badge{display:inline-block;font-size:12px;font-weight:700;border-radius:30px;padding:5px 12px;background:#e8f1ff;color:#225bab}.headerbadge{background:#ffffff20;color:white}.layout{display:grid;grid-template-columns:260px minmax(0,1fr) 280px;gap:18px}.card{background:white;border:1px solid #e1e8f0;border-radius:14px;box-shadow:0 2px 10px #1e3c6414;padding:22px;margin-bottom:18px}nav button{display:block;text-align:left;width:100%;border:1px solid #e1e8f0;background:white;padding:16px;border-radius:10px;color:#1c2733;cursor:pointer;margin:10px 0;font-weight:700}nav button[aria-selected=true]{border-color:#2a6fdb;background:#e8f1ff;color:#225bab}button:focus-visible,a:focus-visible{outline:3px solid #f08c00;outline-offset:3px}.muted{color:#64748b;font-size:13px}.callout{padding:16px;border-radius:10px;background:#eaf7f4;border-left:4px solid #12a594}.limit{background:#fff4df;border-left:4px solid #f08c00;padding:16px;border-radius:10px}.step{font-size:11px;letter-spacing:1.5px;color:#64748b;font-weight:800;margin:24px 0 8px}a{color:#225bab}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:12px}th,td{padding:9px;text-align:left;border-bottom:1px solid #e1e8f0;white-space:nowrap}svg{width:100%;height:auto}details{margin-top:18px}summary{cursor:pointer;font-weight:700}footer{padding:20px 0;color:#64748b;font-size:12px}@media(max-width:1100px){.layout{grid-template-columns:220px minmax(0,1fr)}aside{grid-column:1/-1}}@media(max-width:680px){.layout{display:block}h1{font-size:28px}main{padding:14px}nav{display:grid;grid-template-columns:1fr 1fr;gap:8px}nav button{margin:0}.card{padding:18px}}'''
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TalentRoute | Evidence workspace</title><style>CSS</style><header><span class="badge headerbadge">TALENTROUTE · MODEL INVESTIGATION</span><h1>Understand the evidence. Make a defensible decision.</h1><p>Explore what the learner-support models learned, where their evidence is limited, and whether an added component earns its place.</p><a style="color:white" href="index.html">← Intermediate project and workload explorer</a></header><main><div class="layout"><section class="card"><h3>Investigation path</h3><p class="muted">Choose a question. Follow the evidence and its limits.</p><nav aria-label="Investigations" role="tablist">BUTTONS</nav></section><article class="card" id="investigation" role="tabpanel" aria-live="polite"></article><aside><section class="card"><span class="badge">Evidence scope</span><h3>Development data</h3><p>TRAIN training rows<br>VAL validation rows<br><strong>0 final-test rows</strong> in the three new diagnostics.</p><p class="muted">Added after the recorded final evaluation. Exploratory findings; the separate final candidate and its results remain frozen.</p><a href="../outputs/investigations/manifest.json">Analysis fingerprint</a></section><section class="card"><h3>Decision status</h3><div class="limit"><strong>Further evidence needed</strong><p>The detector's incremental value is unresolved. Keep the simpler reference pending independent evaluation.</p></div></section></aside></div><footer>Inspired by MAAI7101 Week 10: Debugging ML Models, Saravanan Thirumuruganathan. Independent TalentRoute implementation using actual OULAD development outputs. No synthetic learner outcomes or assumed clean labels.</footer></main><script>const cases=DATA;function show(key){const c=cases.find(x=>x.key===key);document.getElementById('investigation').innerHTML=`<span class="badge">${c.title}</span><h2>${c.question}</h2><div class="step">1 · EXPECTED PATTERN</div><p>${c.expectation}</p><div class="step">2 · OBSERVED EVIDENCE</div><div class="callout">${c.result}</div><div class="step">3 · INTERPRETATION LIMIT</div><div class="limit">${c.limits}</div><details><summary>Inspect charts and exact results</summary>${c.evidence}</details>`;document.querySelectorAll('nav button').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.key===key)))}document.querySelectorAll('nav button').forEach(b=>b.addEventListener('click',()=>show(b.dataset.key)));show('learning');</script></html>'''
for k,v in [('CSS',css),('BUTTONS',''.join(f'<button role="tab" data-key="{c["key"]}" aria-controls="investigation" aria-selected="false">{c["title"]}</button>' for c in cards)),('TRAIN',f'{manifest["train_n"]:,}'),('VAL',f'{manifest["validation_n"]:,}'),('DATA',json.dumps(cards).replace('</','<\\/'))]:page=page.replace(k,v)
(ROOT/'review').mkdir(parents=True,exist_ok=True)
(ROOT/'review/investigations.html').write_text(page)
print('Built investigations.html')
